int generate_random_k(WC_RNG* rng, int size, mp_int* k, mp_int* order) {
    int ret = 0;
    byte* randomBytes = NULL;
    mp_int max, temp;

    // Allocate memory for the random bytes
    randomBytes = (byte*)malloc(size);
    if (!randomBytes) {
        return MEMORY_E;
    }

    // Generate random bytes
    ret = wc_RNG_GenerateBlock(rng, randomBytes, size);
    if (ret != 0) {
        free(randomBytes);
        return ret;
    }

    // Initialize and set max to order
    mp_init(&max);
    mp_init(&temp);
    mp_copy(order, &max);

    // Convert the byte array to an integer
    mp_read_unsigned_bin(k, randomBytes, size);

    // Ensure k is in [1, order-1]
    mp_sub_d(&max, 1, &max);

    // If k is greater than max, reduce it by mod operation
    if (mp_cmp(k, &max) == MP_GT) {
        mp_mod(k, &max, &temp);
        mp_copy(&temp, k);
    }

    // Check if k is zero and adjust if needed
    if (mp_cmp_d(k, 0) == MP_EQ) {
        mp_set_int(k, 1);
    }

    mp_clear(&max);
    mp_clear(&temp);
    free(randomBytes);

    return 0;
}

int wc_GenerateECCRandomK(WC_RNG* rng, int size, mp_int* k, mp_int* order) {
    int ret = 0;
    byte* randBytes = NULL;
    int randSize = size;
    int i;

    if (rng == NULL || k == NULL || order == NULL || size <= 0) {
        return BAD_FUNC_ARG;
    }

    randBytes = (byte*)XMALLOC(randSize, 0);
    if (randBytes == NULL) {
        return MEMORY_E;
    }

    ret = wc_RNG_GenerateBlock(rng, randBytes, randSize);
    if (ret != 0) {
        XFREE(randBytes, 0);
        return ret;
    }

    mp_init(k);

    mp_read_unsigned_bin(k, randBytes, randSize);

    if (mp_cmp(k, order) != MP_LT) {
        mp_sub_d(k, 1, k);
    }

    if (mp_cmp_d(k, 0) == MP_EQ) {
        mp_set_int(k, 1);
    }

    XFREE(randBytes, 0);
    return ret;
}

#include <wolfcrypt/wcrypto.h>
#include <wolfcrypt/rand.h>

int GenerateECRandomK(WC_RNG* rng, int size, mp_int* k, mp_int* order) {
    int ret = 0;
    byte* randBytes = NULL;
    mp_int temp;

    randBytes = (byte*)XMALLOC(size, NULL, DYNAMIC_TYPE_TMP_BUFFER);
    if (!randBytes) {
        return MEMORY_E;
    }

    if ((ret = wc_RNG_GenerateBlock(rng, randBytes, size)) != 0) {
        XFREE(randBytes, NULL, DYNAMIC_TYPE_TMP_BUFFER);
        return ret;
    }

    mp_init(&temp);
    if ((ret = mp_read_unsigned_octet(&temp, randBytes, size)) != 0) {
        XFREE(randBytes, NULL, DYNAMIC_TYPE_TMP_BUFFER);
        mp_clear(&temp);
        return ret;
    }

    if ((ret = mp_mod(&temp, order, k)) != 0) {
        XFREE(randBytes, NULL, DYNAMIC_TYPE_TMP_BUFFER);
        mp_clear(&temp);
        return ret;
    }

    if (mp_cmp_int(k, 0) == 0) {
        if ((ret = mp_set_int(k, 1)) != 0) {
            XFREE(randBytes, NULL, DYNAMIC_TYPE_TMP_BUFFER);
            mp_clear(&temp);
            return ret;
        }
    }

    XFREE(randBytes, NULL, DYNAMIC_TYPE_TMP_BUFFER);
    mp_clear(&temp);
    return ret;
}

int wc_GenerateRandomK(WC_RNG* rng, int size, mp_int* k, mp_int* order) {
    int ret = 0;
    byte* randBytes = NULL;
    mp_int upper;
    mp_int tmp;
    mp_int one;

    randBytes = (byte*)XMALLOC(size, 0);
    if (randBytes == NULL) {
        return MEMORY_E;
    }

    ret = wc_RNG_GenerateBlock(rng, randBytes, size);
    if (ret != 0) {
        XFREE(randBytes, 0);
        return ret;
    }

    mp_init(&upper);
    mp_init(&tmp);
    mp_init(&one);

    mp_set(&one, 1);

    // Convert byte array to mp_int
    if ((ret = mp_read_unsigned_octets(&tmp, randBytes, size)) != MP_OKAY) {
        ret = MP_TO_E(ret);
        goto cleanup;
    }

    // Ensure k is less than order
    if ((ret = mp_sub(&one, order, &upper)) != MP_OKAY) {
        ret = MP_TO_E(ret);
        goto cleanup;
    }

    if ((ret = mp_cmp_mag(&tmp, &upper)) == MP_GT) {
        ret = mp_div(&tmp, order, &tmp, NULL);
    }

    // Ensure k is greater than zero
    if ((ret = mp_cmp(&tmp, &one)) == MP_LT) {
        if ((ret = mp_add(&tmp, &one, &tmp)) != MP_OKAY) {
            ret = MP_TO_E(ret);
            goto cleanup;
        }
    }

    mp_copy(&tmp, k);

cleanup:
    mp_clear(&upper);
    mp_clear(&tmp);
    mp_clear(&one);
    XFREE(randBytes, 0);
    return ret;
}

