int generate_random_k(WC_RNG* rng, int size, mp_int* k, mp_int* order) {
    int ret = 0;
    byte* randomBytes = NULL;

    if (!rng || !k || !order) {
        return BAD_FUNC_ARG;
    }

    randomBytes = (byte*)malloc(size);
    if (!randomBytes) {
        return MEMORY_E;
    }

    if ((ret = wc_RNG_GenerateBlock(rng, randomBytes, size)) != 0) {
        free(randomBytes);
        return ret;
    }

    if ((ret = mp_read_radix(k, (char*)randomBytes, 16)) != MP_OKAY) {
        free(randomBytes);
        return ret;
    }

    if (mp_cmp(k, order) >= 0) {
        mp_div(k, order, k, NULL);
    }

    if (mp_cmp_d(k, 0) != MP_GT) {
        mp_set(k, 1);
    }

    free(randomBytes);
    return 0;
}
